        <h2>{data.title}</h2>
        <label><input type="checkbox" checked={autoRefresh} onChange={this.handleToggle}/> Odświeżaj co 30 s</label>
        <p>Zgłoszeń: {data.count}</p>
      </section>
    );
  }
}

